from docx import Document

def dump_table(table, indent=""):
    for r, row in enumerate(table.rows):
        for c, cell in enumerate(row.cells):
            print(f"{indent}  Row {r}, Col {c}: {cell.text!r}")
            for nested in cell.tables:
                print(f"{indent}    Nested Table:")
                dump_table(nested, indent + "    ")

doc = Document("offer_letter_filled.docx")
print("--- Paragraphs ---")
for para in doc.paragraphs:
    if para.text.strip():
        print(para.text)

print("\n--- Tables ---")
for i, table in enumerate(doc.tables):
    print(f"Table {i}:")
    dump_table(table)
